<?php
require __DIR__.'/includes/bootstrap.php';
function farm_guide_answer(string $question): string {
    $q=mb_strtolower($question);
    if(preg_match('/(buy|buyer|variety|grain|which rice|what rice|seed)/u',$q)) return "To choose a grain to buy, first decide what you need it for (daily meals, seed, feed, or resale), your preferred variety, quality, quantity, and budget. Ask the seller about variety, harvest or milling date, moisture/storage, and whether the amount is per kilo or per sack.\n\nYou can browse current local listings in the Market. Availability and prices are set by each farmer and may change.";
    if(preg_match('/(plant|planting|season|grow|crop|sow|palay|rice)/u',$q)) return "I can share general ideas, but I do not have live local weather, soil, water, or crop-price data. Those details matter before choosing what to plant.\n\nFor a useful planning conversation, note your barangay, planting month, water source, soil conditions, available land, and the crop you are considering. Then compare those with current advice from your Municipal Agriculture Office or local agricultural technician.\n\nIn general, rice needs dependable water and a suitable planting calendar. Corn and other grains have different water and soil needs. Please treat this as a starting point, not a promise of yield or profit.";
    if(preg_match('/(list|sell|product|market|order|payment|pickup|delivery|account)/u',$q)) return "To sell: create a Farmer account, choose Add product, then enter the product name, category, price per unit, available quantity, and pickup location.\n\nTo buy: create a Buyer account, browse a listing, choose a quantity, and send an order request. The order request is not a payment. The buyer and farmer confirm payment and pickup or delivery directly.";
    return "I can help with basic marketplace steps and general grain questions. Try asking how to list a harvest, what details to ask before buying rice, or what local information to gather before choosing a crop.\n\nI am a simple starter guide and am not connected to a live AI service or current local agriculture data yet.";
}
if($_SERVER['REQUEST_METHOD']==='POST'){$body=json_decode(file_get_contents('php://input'),true)??[];$question=trim((string)($body['question']??''));header('Content-Type: application/json; charset=utf-8');if($question===''||mb_strlen($question)>1000){http_response_code(422);echo json_encode(['answer'=>'Please enter a question under 1,000 characters.']);exit;}echo json_encode(['answer'=>farm_guide_answer($question)],JSON_UNESCAPED_UNICODE);exit;}
$pageTitle='Farm Guide';require __DIR__.'/includes/header.php';
?>
<section class="page-intro"><span class="eyebrow" style="color:var(--green)">Ask the Farm Guide</span><h1 style="font-size:clamp(2.1rem,4vw,3.4rem)">A helpful place to start.</h1><p>Ask about using the market, buying grains, or what information to gather before making a crop plan.</p></section><section class="panel chat-panel"><div class="chat-feed" id="assistant-feed"><div class="chat-bubble">Hello! I can explain how to use the marketplace and share general grain-buying or crop-planning pointers. What would you like to know?</div></div><form class="chat-form" id="assistant-form"><input name="question" maxlength="1000" placeholder="Example: What should I ask before buying rice?" aria-label="Your question" required><button class="button">Ask</button></form><p class="disclaimer" style="margin-top:15px"><strong>About this starter:</strong> This is a simple rule-based demo, not a connected AI model. It does not know live weather, local market prices, or your field conditions. For planting decisions, confirm current guidance with the local Municipal Agriculture Office or agricultural technician.</p></section>
